@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-dark: #0D1B2A;
  --bg-darker: #0A1420;
  --bg-charcoal: #1B2838;
  --primary-navy: #15295A;
  --accent-green: #6CC24A;
  --dark-gray: #3C424B;
  --electric-blue: #00B4D8;
  --teal: #0077B6;
  --text-main: #E0E1DD;
  --text-muted: #A0AAB2;
  --white: #FFFFFF;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-main);
  line-height: 1.6;
}

a {
  text-decoration: none;
  color: var(--electric-blue);
  transition: color 0.3s;
}
a:hover {
  color: var(--teal);
}

ul {
  list-style: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  color: var(--white);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: 3.5rem; margin-bottom: 1.5rem; }
h2 { font-size: 2.5rem; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 1rem; }
p { margin-bottom: 1.5rem; }

/* Buttons */
.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.3s ease;
  text-align: center;
}

.btn-primary {
  background-color: var(--electric-blue);
  color: var(--bg-darker);
}
.btn-primary:hover {
  background-color: var(--teal);
  color: var(--white);
}

.btn-secondary {
  background-color: transparent;
  color: var(--electric-blue);
  border: 2px solid var(--electric-blue);
}
.btn-secondary:hover {
  background-color: var(--electric-blue);
  color: var(--bg-darker);
}

.btn-accent {
  background-color: var(--accent-green);
  color: var(--bg-darker);
}
.btn-accent:hover {
  background-color: #5bb039;
}

/* Header & Nav */
header {
  background-color: var(--bg-darker);
  border-bottom: 1px solid var(--dark-gray);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background-color: var(--electric-blue);
  border-radius: 4px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-item {
  position: relative;
}

.nav-link {
  color: var(--text-main);
  font-weight: 500;
}
.nav-link:hover {
  color: var(--electric-blue);
}

.dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  background-color: var(--bg-charcoal);
  min-width: 200px;
  padding: 10px 0;
  border-radius: 4px;
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
  display: none;
  border: 1px solid var(--dark-gray);
}
.nav-item:hover .dropdown {
  display: block;
}
.dropdown li a {
  display: block;
  padding: 10px 20px;
  color: var(--text-main);
}
.dropdown li a:hover {
  background-color: var(--primary-navy);
  color: var(--white);
}

/* Hero Section */
.hero {
  padding: 100px 0;
  background: linear-gradient(135deg, var(--bg-dark) 0%, var(--primary-navy) 100%);
  text-align: center;
}
.hero-content {
  max-width: 800px;
  margin: 0 auto;
}
.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
}
.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Sections */
.section {
  padding: 80px 0;
}
.section-bg-alt {
  background-color: var(--bg-charcoal);
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}
.section-label {
  color: var(--electric-blue);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 0.5rem;
  display: block;
}

/* Grids */
.grid {
  display: grid;
  gap: 2rem;
}
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }

/* Cards */
.card {
  background-color: var(--bg-charcoal);
  border: 1px solid var(--dark-gray);
  border-radius: 8px;
  padding: 2rem;
  transition: transform 0.3s, border-color 0.3s;
}
.card:hover {
  transform: translateY(-5px);
  border-color: var(--electric-blue);
}
.card h3 {
  font-size: 1.25rem;
  color: var(--electric-blue);
}

/* Featured Banner */
.featured-banner {
  background-color: var(--primary-navy);
  padding: 2rem;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: -40px auto 40px;
  position: relative;
  z-index: 10;
  border: 1px solid var(--electric-blue);
}

/* Diagrams */
.diagram-container {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 3rem;
  background-color: var(--bg-darker);
  border-radius: 8px;
  border: 1px solid var(--dark-gray);
  margin-top: 2rem;
}
.ecosystem-diagram {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
}
.diagram-node {
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: var(--bg-charcoal);
  border: 2px solid var(--electric-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 1rem;
  font-weight: 600;
  color: var(--white);
  box-shadow: 0 0 20px rgba(0,180,216,0.2);
}
.diagram-link {
  width: 50px;
  height: 2px;
  background-color: var(--electric-blue);
}

/* Tabs */
.tabs-nav {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--dark-gray);
  overflow-x: auto;
}
.tab-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  padding: 1rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.3s;
}
.tab-btn:hover, .tab-btn.active {
  color: var(--white);
  border-bottom-color: var(--electric-blue);
}
.tab-content {
  display: none;
  animation: fadeIn 0.5s;
}
.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.accordion-item {
  background-color: var(--bg-charcoal);
  border: 1px solid var(--dark-gray);
  border-radius: 8px;
  overflow: hidden;
}
.accordion-header {
  padding: 1.5rem;
  background-color: var(--bg-charcoal);
  color: var(--white);
  font-weight: 600;
  font-size: 1.25rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  border: none;
  width: 100%;
  text-align: left;
}
.accordion-header:hover {
  background-color: var(--primary-navy);
}
.accordion-icon {
  font-size: 1.5rem;
  color: var(--electric-blue);
  transition: transform 0.3s;
}
.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
}
.accordion-body {
  padding: 0 1.5rem;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out, padding 0.3s ease;
  background-color: var(--bg-darker);
}
.accordion-item.active .accordion-body {
  padding: 1.5rem;
  max-height: 500px;
}

/* Stats Circular Indicators */
.stats-container {
  display: flex;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.stat-circle {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  border: 4px solid var(--electric-blue);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 1rem;
  background-color: var(--bg-charcoal);
  box-shadow: inset 0 0 20px rgba(0,180,216,0.1);
}
.stat-number {
  font-size: 3rem;
  font-weight: 700;
  color: var(--white);
  line-height: 1;
  margin-bottom: 0.5rem;
}
.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Timeline */
.timeline {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}
.timeline-item {
  display: flex;
  align-items: center;
  gap: 2rem;
}
.timeline-time {
  width: 120px;
  font-weight: 700;
  color: var(--electric-blue);
  text-align: right;
  flex-shrink: 0;
}
.timeline-bar-container {
  flex-grow: 1;
  height: 20px;
  background-color: var(--bg-charcoal);
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid var(--dark-gray);
}
.timeline-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--teal), var(--electric-blue));
}
.timeline-label {
  width: 300px;
  flex-shrink: 0;
}

/* Testimonial Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  padding: 2rem 0;
}
.carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%;
  padding: 2rem;
  text-align: center;
}
.testimonial-quote {
  font-size: 1.5rem;
  font-style: italic;
  margin-bottom: 1.5rem;
}
.testimonial-author {
  font-weight: 700;
  color: var(--electric-blue);
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--dark-gray);
  cursor: pointer;
  transition: background-color 0.3s;
}
.dot.active {
  background-color: var(--electric-blue);
}

/* Form */
.form-group {
  margin-bottom: 1.5rem;
}
.form-label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
}
.form-control {
  width: 100%;
  padding: 12px;
  background-color: var(--bg-darker);
  border: 1px solid var(--dark-gray);
  border-radius: 4px;
  color: var(--white);
  font-family: inherit;
}
.form-control:focus {
  outline: none;
  border-color: var(--electric-blue);
}
textarea.form-control {
  resize: vertical;
  min-height: 100px;
}

/* Lists */
.check-list li {
  position: relative;
  padding-left: 2rem;
  margin-bottom: 1rem;
}
.check-list li::before {
  content: '✓';
  position: absolute;
  left: 0;
  top: 0;
  color: var(--accent-green);
  font-weight: bold;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--primary-navy);
  padding: 1.5rem;
  z-index: 1000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 -4px 10px rgba(0,0,0,0.5);
  border-top: 1px solid var(--electric-blue);
}
.cookie-banner p {
  margin-bottom: 0;
  max-width: 800px;
}
.cookie-buttons {
  display: flex;
  gap: 1rem;
}

/* Footer */
footer {
  background-color: var(--bg-darker);
  padding: 60px 0 30px;
  border-top: 1px solid var(--dark-gray);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  margin-bottom: 1.5rem;
  color: var(--white);
}
.footer-col ul li {
  margin-bottom: 0.75rem;
}
.footer-col a {
  color: var(--text-muted);
}
.footer-col a:hover {
  color: var(--electric-blue);
}
.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--dark-gray);
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 992px) {
  h1 { font-size: 2.5rem; }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-container { gap: 1.5rem; }
  .timeline-item { flex-direction: column; align-items: flex-start; gap: 0.5rem; }
  .timeline-time { text-align: left; }
  .timeline-bar-container { width: 100%; }
}

@media (max-width: 768px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .nav-links { display: none; } /* Simplified for prototype */
  .featured-banner { flex-direction: column; text-align: center; gap: 1rem; }
  .cookie-banner { flex-direction: column; gap: 1rem; text-align: center; }
  .ecosystem-diagram { flex-direction: column; }
  .diagram-link { width: 2px; height: 30px; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Tabs Logic
  const tabGroups = document.querySelectorAll('.tabs-container');
  tabGroups.forEach(group => {
    const tabBtns = group.querySelectorAll('.tab-btn');
    const tabContents = group.querySelectorAll('.tab-content');

    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        const targetContent = group.querySelector(`#${targetId}`);
        if(targetContent) targetContent.classList.add('active');
      });
    });
  });

  // Accordion Logic
  const accordions = document.querySelectorAll('.accordion-header');
  accordions.forEach(header => {
    header.addEventListener('click', () => {
      const item = header.parentElement;
      const parent = item.parentElement;

      // Close others
      parent.querySelectorAll('.accordion-item').forEach(otherItem => {
        if(otherItem !== item) {
          otherItem.classList.remove('active');
        }
      });

      // Toggle current
      item.classList.toggle('active');
    });
  });

  // Carousel Logic
  const carousels = document.querySelectorAll('.carousel');
  carousels.forEach(carousel => {
    const inner = carousel.querySelector('.carousel-inner');
    const dots = carousel.querySelectorAll('.dot');

    dots.forEach((dot, index) => {
      dot.addEventListener('click', () => {
        dots.forEach(d => d.classList.remove('active'));
        dot.classList.add('active');

        inner.style.transform = `translateX(-${index * 100}%)`;
      });
    });
  });

  // Cookie Banner Logic
  const cookieBanner = document.getElementById('cookie-banner');
  if(cookieBanner) {
    const acceptBtn = document.getElementById('cookie-accept');
    const declineBtn = document.getElementById('cookie-decline');

    if(!localStorage.getItem('cookieConsent')) {
      cookieBanner.style.display = 'flex';
    } else {
      cookieBanner.style.display = 'none';
    }

    const dismissBanner = () => {
      cookieBanner.style.display = 'none';
      localStorage.setItem('cookieConsent', 'true');
    };

    if(acceptBtn) acceptBtn.addEventListener('click', dismissBanner);
    if(declineBtn) declineBtn.addEventListener('click', dismissBanner);
  }

  // Form Validation Logic
  const demoForm = document.getElementById('demo-form');
  if(demoForm) {
    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Basic validation check (html5 handles most of it due to 'required' attributes)
      if(demoForm.checkValidity()) {
        alert('Demo Request Submitted Successfully!');
        demoForm.reset();
      } else {
        demoForm.reportValidity();
      }
    });
  }

});
